/* WMM brand: black surfaces and lime accents. Auth and records are untouched. */
(function(){const root=document.documentElement;root.dataset.theme='dark';root.style.colorScheme='dark';try{localStorage.setItem('wmm-team-theme','dark')}catch{}document.addEventListener('DOMContentLoaded',()=>{document.querySelectorAll('[data-theme-toggle]').forEach(b=>b.hidden=true);document.querySelector('meta[name="theme-color"]')?.setAttribute('content','#050505')})})();
